  if (op === 'profielmis') { res.setHeader('cache-control', 'no-store'); const l = await kv.raw(['LRANGE', 'cur:profiel:mis', '0', '49']).catch(() => []); return res.status(200).json({ laatste: await kv.get('cur:profiel:laatste').catch(() => null), mis: (l || []).map(x => { try { return JSON.parse(x); } catch { return null; } }) }); }
  if (op === 'profielen') { res.setHeader('cache-control', 'no-store'); const r = await Promise.all([0, 4, 8, 12, 16, 20, 24, 28].map(off => curProfielen(4, off))); return res.status(200).json(r); }
  if (!['GET', 'HEAD'].includes(req.method || 'GET')) return res.status(405).send('Method not allowed');
  const m = CUR_MARKT[q.get('m')] ? q.get('m') : 'en'; const s = String(q.get('s') || '').toLowerCase();
  res.setHeader('content-type', 'text/html; charset=utf-8'); res.setHeader('cache-control', 'public, max-age=600');
  if (!s) { await telBot(req, m, 'hub'); const [cij, vd, gi] = await Promise.all([curCijfers().catch(() => null), curVandaag(m, req.headers['x-vercel-oidc-token']).catch(() => null), gidsIndex().catch(() => null)]); return res.status(200).send(renderHub(m, cij, vd, gi && gi.totaal)); }
  if (s === GIDS_PAD[m]) { const I = await gidsIndex().catch(() => null); if (!I) { res.setHeader('location', hubUrl(m)); return res.status(307).end(); } const cs = String(q.get('b') || '').toLowerCase(), bs = String(q.get('c') || '').toLowerCase(); await telBot(req, m, 'gids');
    if (!cs) return res.status(200).send(renderGidsHome(m, I)); if (!I.cats[cs]) { res.setHeader('location', gidsUrl(m)); return res.status(302).end(); } const items = (await gidsCat(cs)) || [];
    if (!bs) return res.status(200).send(renderGidsCat(m, I, cs, items)); const x = items.find(y => y.slug === bs); if (!x) { res.setHeader('location', gidsUrl(m, cs)); return res.status(308).end(); } return res.status(200).send(renderGidsBedrijf(m, I, cs, items, x)); }
  if (s === 'eigenaar') { res.setHeader('cache-control', 'private, max-age=60'); return res.status(200).send(await renderEigenaar(m, String(q.get('o') || ''), String(q.get('id') || ''))); }
  const o = ONDERWERPEN.find(x => x.slug[m] === s);
